-- Viewmodel-recoil comparison variant of cw_anomaly_val. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "zatvor" in anm_shots, 2.895 units, peak frame 1, home frame 3 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_val"

SWEP.PrintName = "AS “Val” (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

